{"policy":"permit (
    principal is Person,
    action in [Action::"createWorkOrder", Action::"startWork"],
    resource is WorkOrder
)
when {
    principal.roles.contains(Role::"operator")
};

permit (
    principal is Person,
    action == Action::"signOffWorkOrder",
    resource is WorkOrder
)
when {
    (principal.roles.contains(Role::"inspector") || principal.roles.contains(Role::"qualityManager")) &&
    resource.status == WorkOrderStatus::"inProgress" &&
    (context.partCodeMatches || context.hasControlledPartPrefix) &&
    resource.defectCount <= context.acceptanceThreshold
};

forbid (
    principal is Person,
    action == Action::"signOffWorkOrder",
    resource is WorkOrder
)
when {
    (principal.roles.contains(Role::"inspector") || principal.roles.contains(Role::"qualityManager")) &&
    (
        resource.status != WorkOrderStatus::"inProgress" ||
        !(context.partCodeMatches || context.hasControlledPartPrefix) ||
        resource.defectCount > context.acceptanceThreshold
    )
};

permit (
    principal is Person,
    action == Action::"releaseToProduction",
    resource is ProductionRelease
)
when {
    principal.roles.contains(Role::"productionSupervisor") &&
    resource.workOrder.status == WorkOrderStatus::"signedOff"
};

permit (
    principal is Person,
    action == Action::"viewQualityLog",
    resource is QualityLog
)
when {
    principal.roles.contains(Role::"auditor")
};"}
